1	//structure similar to ImageData, but without prototype chain or clamped constraint, easy to consume with sharp
2	
3	import type { Texture } from "three";
4	
5	export type CanvasImage = Exclude<CanvasImageSource, SVGImageElement | VideoFrame>;
6	
7	export function makeImageData(data: Uint8ClampedArray | Uint8Array | null, width: number, height: number): ImageData {
8		if (!data) {
9			data = new Uint8ClampedArray(width * height * 4);
10		}
11		if (data instanceof Uint8Array) {
12			data = new Uint8ClampedArray(data.buffer, data.byteOffset, data.length);
13		}
14		if (typeof ImageData != "undefined") {
15			return new ImageData(data as any, width, height);
16		} else {
17			return { data: data as any, width, height, colorSpace: "srgb" } as any;
18		}
19	}
20	
21	export async function pixelsToImageFile(imgdata: ImageData, format: "png" | "webp", quality: number) {
22		if (typeof HTMLCanvasElement != "undefined") {
23			let cnv = document.createElement("canvas");
24			cnv.width = imgdata.width;
25			cnv.height = imgdata.height;
26			let ctx = cnv.getContext("2d", { willReadFrequently: true })!;
27			ctx.putImageData(imgdata, 0, 0);
28			return canvasToImageFile(cnv, format, quality);
29		} else {
30			const sharp = require("sharp") as typeof import("sharp");
31			let img = sharp(imgdata.data, { raw: { width: imgdata.width, height: imgdata.height, channels: 4 } });
32			if (format == "png") {
33				return img.png().toBuffer();
34			} else if (format == "webp") {
35				return img.webp({ quality: quality * 100 }).toBuffer();
36			} else {
37				throw new Error("unknown format");
38			}
39		}
40	}
41	
42	
43	let warnedstripalpha = false;
44	export async function fileToImageData(file: Uint8Array, mimetype: "image/png" | "image/jpg", stripAlpha: boolean) {
45		if (typeof ImageDecoder != "undefined") {
46			//typescript claims premultiplyAlpha option doesn't exist
47			let decoder = new ImageDecoder({ data: file, type: mimetype, premultiplyAlpha: (stripAlpha ? "none" : "default"), colorSpaceConversion: "none" } as any);
48			let frame = await decoder.decode();
49			let pixels = new Uint8Array(frame.image.allocationSize());
50			frame.image.copyTo(pixels);
51			let pixelcount = frame.image.visibleRect!.width * frame.image.visibleRect!.height;
52			if (frame.image.format == "BGRX" || frame.image.format == "RGBX") {
53				stripAlpha = true;
54			}
55			if (frame.image.format == "BGRA" || frame.image.format == "BGRX") {
56				for (let i = 0; i < pixelcount; i++) {
57					let tmp = pixels[i * 4 + 0];
58					pixels[i * 4 + 0] = pixels[i * 4 + 2];
